<?php require_once __DIR__.'/../config/conexao.php'; require_once __DIR__.'/../includes/funcoes.php'; $id=(int)($_GET['id']??0);$st=$pdo->prepare('SELECT p.*,c.nome AS categoria FROM produtos p LEFT JOIN categorias c ON c.id=p.categoria_id WHERE p.id=? AND p.ativo=1');$st->execute([$id]);$p=$st->fetch();if(!$p){http_response_code(404);} ?>
<!DOCTYPE html><html lang="pt-BR"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Detalhes | Doppio Mocha</title><link rel="stylesheet" href="../css/code.css"></head><body><?php require __DIR__.'/../includes/cabecalho.php'; ?><main class="secao-produtos"><?php if(!$p): ?><h2>Produto não encontrado</h2><a href="produtos.php">Voltar ao cardápio</a><?php else: ?><div class="detalhe-produto"><img src="../imagens/<?= h($p['imagem']?:'cafe.png') ?>" alt="<?= h($p['nome']) ?>"><div><span class="subtitulo-secao"><?= h($p['categoria']??'Especial') ?></span><h1><?= h($p['nome']) ?></h1><p><?= h($p['descricao']) ?></p><p class="preco"><?= moeda((float)$p['preco']) ?></p><p class="texto-estoque"><?= (int)$p['estoque']>0?'Disponível':'Indisponível no momento' ?></p><?php if((int)$p['estoque']>0): ?><button class="botao-comprar" type="button" data-id="<?= (int)$p['id'] ?>" data-nome="<?= h($p['nome']) ?>" data-preco="<?= h((string)$p['preco']) ?>" data-imagem="../imagens/<?= h($p['imagem']?:'cafe.png') ?>">Adicionar ao carrinho</button><?php endif; ?><p><a href="produtos.php">← Voltar ao cardápio</a></p></div></div><?php endif; ?></main><?php require __DIR__.'/../includes/rodape.php'; ?></body></html>
